(() => {
  const to = (target, vars = {}) => {
    const el = typeof target === 'string' ? document.querySelector(target) : target;
    if (!el) return;
    const duration = (vars.duration || 0.3) * 1000;
    const keyframes = [{}, {}];
    if (vars.opacity !== undefined) {
      keyframes[1].opacity = vars.opacity;
    }
    if (vars.y !== undefined || vars.x !== undefined) {
      const x = vars.x || 0;
      const y = vars.y || 0;
      keyframes[1].transform = `translate(${x}px, ${y}px)`;
    }
    el.animate(keyframes, { duration, easing: vars.ease || 'ease-out', fill: 'forwards' });
  };
  window.gsap = { to };
})();
